// Generated by QA-AI-Framework — Playwright Automation Agent (consolidation pass)
//
// Consolidates step definitions that were independently authored, identically, in more
// than one steps file during parallelized generation (dash.steps.ts, invoice.steps.ts,
// waiver.steps.ts all defined these verbatim) — this is a genuine Cucumber
// AmbiguousDefinitionError hazard, not a stylistic duplication. Each duplicate has been
// removed from its original file; only this shared copy remains.

import { Given, When } from '@cucumber/cucumber';
import { ScenarioContext } from '../../../Framework/src/utils/ScenarioContext';
import { resolvePassword } from '../../../Framework/src/utils/passwordResolver';
import { getSharedBrowser } from '../../../Framework/src/helper/hooks';
import { getAuthenticatedPage } from '../../../Framework/src/helper/auth-setup';

function resolveRowPassword(row: Record<string, unknown>, column: string): string {
  const key = row[column] as string | undefined;
  return key ? resolvePassword(key) : '';
}

Given('User is logged in as {string}', async function (this: ScenarioContext, role: string) {
  const email = this.testData.Email as string;
  const password = resolveRowPassword(this.testData, 'PasswordKey');

  // Super Admin is currently blocked by the live backend's login rate limiter — skip
  // (not fail) any scenario that needs it so Ranch Admin/Guide scenarios still run for
  // real results. Do not remove this guard without explicit confirmation that Super
  // Admin is unlocked again.
  if (email?.toLowerCase().includes('superadmin') || role?.toLowerCase().includes('super admin')) {
    return 'skipped';
  }

  // Reuses a cached per-role session instead of an interactive UI login on every single
  // scenario (auto-refreshing it if it's gone stale) — see auth-setup.ts's
  // getAuthenticatedPage() for why: the live backend throttles/locks out accounts after a
  // burst of rapid logins, which repeated interactive logins across ~500 scenarios
  // reliably tripped.
  const browser = getSharedBrowser();
  await this.context?.close();
  const authed = await getAuthenticatedPage(browser, email, password);
  this.context = authed.context;
  this.page = authed.page;
  this.testData.Role = role;
});

When('I set the viewport to {int} by {int}', async function (this: ScenarioContext, width: number, height: number) {
  await this.page.setViewportSize({ width, height });
});

When('I press Tab repeatedly from page load', async function (this: ScenarioContext) {
  for (let i = 0; i < 8; i += 1) {
    await this.page.keyboard.press('Tab');
  }
});
